  ctx.strokeRect(mapBB[0], mapBB[1], mapBB[2] - mapBB[0], mapBB[3] - mapBB[1]); ctx.setLineDash([]);
  // university grounds
  ctx.fillStyle = css('--campus-fill'); ctx.fill(campusPath);
  ctx.lineWidth = 1.5 * px; ctx.strokeStyle = css('--campus-edge'); ctx.stroke(campusPath);
  // buildings (tile-culled)
