    const x0 = Math.floor(wx(0) / TILE) - 1, x1 = Math.floor(wx(W) / TILE) + 1, y0 = Math.floor(wy(H) / TILE) - 1, y1 = Math.floor(wy(0) / TILE) + 1;
    ctx.fillStyle = css('--bld');
