    ctx.fillStyle = p.kind === 'hub' ? css('--accent') : p.kind === 'dorm' ? archCol(0) : css('--ink-2'); ctx.fillText(label, rx + 4, y); if (p.kind === 'dorm') { ctx.fillStyle = archCol(0); ctx.fillRect(x - 4, y - 4, 8, 8); continue; }
