  ctx.clearRect(0, 0, W, H);
  let home = 0, trav = 0, camp = 0, riding = 0;
  const byMode = [0, 0, 0, 0, 0, 0, 0, 0], inBld = new Array(BLDS.length).fill(0), load = new Map();
  travellers = [];
