function timeChart(hostId, series, colors, names, opts) {
  const host = $(hostId), w = 720, h = opts.h || 220, ml = 40, mr = 10, mt = 8, mb = 22, iw = w - ml - mr, ih = h - mt - mb;
  const tot = new Float64Array(NB); series.forEach(s => s.forEach((v, i) => tot[i] += v));
  const ymax = niceMax(Math.max(...(opts.stack ? tot : series.flatMap(s => Array.from(s)))));
  const X = b => ml + (b + 0.5) / NB * iw, Y = v => mt + ih - v / ymax * ih;
  let svg = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${opts.label}">`;
  svg += '<g class="axis">';
  for (let i = 0; i <= 4; i++) { const v = ymax * i / 4, y = Y(v); svg += `<line x1="${ml}" x2="${w - mr}" y1="${y}" y2="${y}" ${i ? 'stroke-dasharray="2 3"' : ''}/><text x="${ml - 6}" y="${y + 3}" text-anchor="end">${fmt(Math.round(v))}</text>`; }
  for (let hr = 0; hr <= 24; hr += 3) { const x = ml + hr / 24 * iw; svg += `<text x="${x}" y="${h - 6}" text-anchor="middle">${String(hr).padStart(2, '0')}</text>`; }
  svg += '</g>';
  const base = new Float64Array(NB);
  series.forEach((s, si) => {
    if (opts.stack) {
      let d = ''; for (let b = 0; b < NB; b++) d += (b ? 'L' : 'M') + X(b).toFixed(1) + ' ' + Y(base[b] + s[b]).toFixed(1);
      for (let b = NB - 1; b >= 0; b--) d += 'L' + X(b).toFixed(1) + ' ' + Y(base[b]).toFixed(1);
      svg += `<path d="${d}Z" fill="${colors[si]}" stroke="var(--panel)" stroke-width="0.6"/>`;
      for (let b = 0; b < NB; b++) base[b] += s[b];
    } else {
      let d = ''; for (let b = 0; b < NB; b++) d += (b ? 'L' : 'M') + X(b).toFixed(1) + ' ' + Y(s[b]).toFixed(1);
      svg += `<path d="${d}" fill="none" stroke="${colors[si]}" stroke-width="2" stroke-linejoin="round"/>`;
    }
  });
  svg += `<line class="hoverline" x1="0" x2="0" y1="${mt}" y2="${mt + ih}" stroke="var(--ink-2)" stroke-width="1" opacity="0"/>`;
  svg += `<line class="tcursor" data-x0="${ml}" data-w="${iw}" x1="0" x2="0" y1="${mt}" y2="${mt + ih}" stroke="var(--landmark)" stroke-width="1.5"/>`;
  svg += '</svg>';
  host.innerHTML = svg;
  const el = host.firstChild;
  attachTip(host.parentElement, el, x => {
    const b = Math.max(0, Math.min(NB - 1, Math.floor((x - ml) / iw * NB)));
    const hl = el.querySelector('.hoverline'); hl.setAttribute('x1', X(b)); hl.setAttribute('x2', X(b)); hl.setAttribute('opacity', 1);
    let rows = series.map((s, i) => [names[i], s[b], colors[i]]).filter(r => r[1] > 0).sort((p, q) => q[1] - p[1]);
    return `<b class="mono">${hhmm(b * BIN)}–${hhmm(b * BIN + BIN)}</b>` + rows.map(r => `<br><i style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${r[2]};margin-right:5px"></i>${r[0]} <b class="mono">${fmt(r[1])}</b>`).join('') + (opts.stack ? `<br><span style="color:var(--muted)">Összesen ${fmt(tot[b])}</span>` : '');
  });
  el.addEventListener('click', e => { const r = el.getBoundingClientRect(); const x = (e.clientX - r.left) * w / r.width; const b = Math.max(0, Math.min(NB - 1, Math.floor((x - ml) / iw * NB))); setTime(b * 5); });
  el.classList.add('clickable');
}
function hbar(hostId, rows, opts) {
  const host = $(hostId), w = 360, rh = 24, ml = opts.ml || 150, mr = 44, h = rows.length * rh + 6;
  const max = niceMax(Math.max(...rows.map(r => r.v)));
  let svg = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${opts.label}">`;
  rows.forEach((r, i) => {
    const y = i * rh + 3, bw = Math.max(r.v ? 3 : 0, r.v / max * (w - ml - mr));
    svg += `<g class="${opts.onClick ? 'clickable' : ''}" data-i="${i}" opacity="${r.off ? .35 : 1}"><rect x="0" y="${y}" width="${w}" height="${rh}" fill="transparent"/>`;
    if (r.icon != null) svg += `<g transform="translate(9 ${y + rh / 2}) scale(8)">${iconSVG(r.icon).replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '').replace(/<title>.*<\/title>/, '')}</g>`;
    svg += `<text class="bar-label" x="${r.icon != null ? 22 : 0}" y="${y + rh / 2 + 4}">${r.label}</text>`;
    svg += `<rect x="${ml}" y="${y + 5}" width="${bw}" height="${rh - 10}" rx="2" fill="${r.color}"/>`;
    svg += `<text class="bar-val" x="${ml + bw + 5}" y="${y + rh / 2 + 4}">${opts.fmt ? opts.fmt(r.v) : fmt(r.v)}</text></g>`;
  });
  host.innerHTML = svg + '</svg>';
  const el = host.firstChild;
  attachTip(host.parentElement, el, (x, y) => { const i = Math.floor((y - 3) / rh); const r = rows[i]; return r ? `${r.label}<br><b class="mono">${opts.fmt ? opts.fmt(r.v) : fmt(r.v)}</b>${r.extra ? '<br>' + r.extra : ''}` : ''; });
  if (opts.onClick) el.querySelectorAll('g[data-i]').forEach(g => g.addEventListener('click', () => opts.onClick(+g.dataset.i)));
}
function histogram(hostId) {
  const host = $(hostId), w = 360, h = 190, ml = 34, mr = 8, mt = 8, mb = 22, iw = w - ml - mr, ih = h - mt - mb;
  const edges = [0, 5, 10, 15, 20, 25, 30, 40, 50, 60, 75, 90, 120];
  const c = new Array(edges.length - 1).fill(0);
  for (const v of SER.tt) for (let i = 0; i < c.length; i++) if (v < edges[i + 1] || i === c.length - 1) { c[i]++; break; }
  const ymax = niceMax(Math.max(...c)), bw = iw / c.length;
  let svg = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Distribution of door-to-door travel time"><g class="axis">`;
  for (let i = 0; i <= 4; i++) { const v = ymax * i / 4, y = mt + ih - v / ymax * ih; svg += `<line x1="${ml}" x2="${w - mr}" y1="${y}" y2="${y}" ${i ? 'stroke-dasharray="2 3"' : ''}/><text x="${ml - 5}" y="${y + 3}" text-anchor="end">${fmt(Math.round(v))}</text>`; }
  c.forEach((_, i) => { if (i % 2 === 0) svg += `<text x="${ml + i * bw}" y="${h - 6}" text-anchor="middle">${edges[i]}</text>`; });
  svg += `<text x="${w - mr}" y="${h - 6}" text-anchor="end">min</text></g>`;
  c.forEach((v, i) => { const bh = v / ymax * ih; svg += `<rect data-i="${i}" x="${ml + i * bw + 1}" y="${mt + ih - bh}" width="${bw - 2}" height="${bh}" rx="2" fill="${pal()[0]}"/>`; });
  host.innerHTML = svg + '</svg>';
  attachTip(host.parentElement, host.firstChild, x => { const i = Math.floor((x - ml) / bw); return c[i] != null ? `${edges[i]}–${edges[i + 1]} min<br><b class="mono">${fmt(c[i])}</b> cases` : ''; });
}
function arrChart() {
  const host = $('chArr'), w = 720, h = 210, ml = 40, mr = 10, mt = 8, mb = 22, iw = w - ml - mr, ih = h - mt - mb;
  const ymax = niceMax(Math.max(...SER.arr, ...SER.dep)), mid = mt + ih / 2, bw = iw / 24;
  const Y = v => v / ymax * ih / 2;
  let svg = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Óránkénti érkezések és távozások a campusokon"><g class="axis">`;
  [-1, -.5, 0, .5, 1].forEach(f => { const y = mid - f * ih / 2; svg += `<line x1="${ml}" x2="${w - mr}" y1="${y}" y2="${y}" ${f ? 'stroke-dasharray="2 3"' : ''}/><text x="${ml - 6}" y="${y + 3}" text-anchor="end">${fmt(Math.abs(Math.round(f * ymax)))}</text>`; });
  for (let hr = 0; hr <= 24; hr += 3) svg += `<text x="${ml + hr * bw}" y="${h - 6}" text-anchor="middle">${String(hr).padStart(2, '0')}</text>`;
  svg += '</g>';
  for (let i = 0; i < 24; i++) {
    const a = Y(SER.arr[i]), d = Y(SER.dep[i]);
    if (a) svg += `<rect x="${ml + i * bw + 2}" y="${mid - a - 1}" width="${bw - 4}" height="${a}" rx="2" fill="${pal()[0]}"/>`;
    if (d) svg += `<rect x="${ml + i * bw + 2}" y="${mid + 1}" width="${bw - 4}" height="${d}" rx="2" fill="${pal()[1]}"/>`;
  }
  svg += `<line class="tcursor" data-x0="${ml}" data-w="${iw}" x1="0" x2="0" y1="${mt}" y2="${mt + ih}" stroke="var(--landmark)" stroke-width="1.5"/>`;
  host.innerHTML = svg + '</svg>';
  attachTip(host.parentElement, host.firstChild, x => { const i = Math.floor((x - ml) / bw); return i >= 0 && i < 24 ? `<b class="mono">${String(i).padStart(2, '0')}:00–${String(i + 1).padStart(2, '0')}:00</b><br>Érkezik a campusra <b class="mono">${fmt(SER.arr[i])}</b><br>Elhagyja a campust <b class="mono">${fmt(SER.dep[i])}</b>` : ''; });
  $('lgArr').innerHTML = `<span><i style="background:${pal()[0]}"></i>Érkezések</span><span><i style="background:${pal()[1]}"></i>Távozások</span>`;
}
function bldChart() {
  const host = $('chBld'), w = 720, rh = 26, ml = 150, mr = 50;
  const rows = BLDS.map((b, i) => { const by = FACS.map((_, f) => F.filter(a => a.b === i && a.f === f).length); return { i, b, by, n: by.reduce((s, v) => s + v, 0) }; }).sort((p, q) => q.n - p.n);
  const max = niceMax(Math.max(1, ...rows.map(r => r.n))), h = rows.length * rh + 22, iw = w - ml - mr;
  let svg = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Arrivals per building split by faculty"><g class="axis">`;
  for (let k = 0; k <= 4; k++) { const x = ml + k / 4 * iw; svg += `<line x1="${x}" x2="${x}" y1="0" y2="${h - 18}" ${k ? 'stroke-dasharray="2 3"' : ''}/><text x="${x}" y="${h - 4}" text-anchor="middle">${fmt(Math.round(max * k / 4))}</text>`; }
  svg += '</g>';
  rows.forEach((r, j) => {
    const y = j * rh + 2; let x = ml;
    svg += `<g data-j="${j}"><rect x="0" y="${y}" width="${w}" height="${rh}" fill="transparent"/><text class="bar-label" x="0" y="${y + rh / 2 + 4}">${r.b.label}</text>`;
    r.by.forEach((v, f) => { if (!v) return; const bw = v / max * iw; svg += `<rect x="${x}" y="${y + 5}" width="${Math.max(1, bw - 2)}" height="${rh - 10}" rx="2" fill="${facCol(f)}"/>`; x += bw; });
    svg += `<text class="bar-val" x="${x + 5}" y="${y + rh / 2 + 4}">${fmt(r.n)}</text></g>`;
  });
  host.innerHTML = svg + '</svg>';
  attachTip(host.parentElement, host.firstChild, (x, y) => { const r = rows[Math.floor((y - 2) / rh)]; return r ? `<b>${r.b.label}</b> · ${r.b.campus} campus<br><span style="color:var(--muted)">${r.b.use}</span>` + r.by.map((v, f) => v ? `<br><i style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${facCol(f)};margin-right:5px"></i>${FACS[f].name} <b class="mono">${fmt(v)}</b>` : '').join('') : ''; });
  $('lgBld').innerHTML = FACS.map((f, i) => `<span><i style="background:${facCol(i)}"></i>${f.name} (${f.key})</span>`).join('');
}
function median(arr) { if (!arr.length) return 0; const s = arr.slice().sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; }

function renderCharts() {
  const mc = MODE_KEYS.map((_, i) => modeCol(i));
  timeChart('chTransit', SER.tr, mc, MODE_NAMES.slice(0, 6), { stack: true, label: 'Úton lévő hallgatók a nap folyamán, közlekedési mód szerint' });
  $('lgTransit').innerHTML = MODE_NAMES.slice(0, 6).map((n, i) => `<span><i style="background:${mc[i]}"></i>${n}</span>`).join('');
  const wc = [css('--home'), css('--accent'), css('--landmark')];
  timeChart('chWhere', [SER.where[0], SER.where[1], SER.where[2]], wc, ['Otthon', 'Úton', 'A campuson'], { stack: false, h: 220, label: 'Otthon, úton és a campuson lévő hallgatók a nap folyamán' });
  $('lgWhere').innerHTML = ['Otthon', 'Úton', 'A campuson'].map((n, i) => `<span><i style="background:${wc[i]}"></i>${n}</span>`).join('');
  const ac = S.arch.map((ar, i) => ({ label: ar.name.replace('Private rental – ', 'Rental – '), v: F.filter(a => a.a === i).length, color: archCol(i), off: !st.arch.has(i), extra: ar.excel }));
  hbar('chArch', ac, { label: 'Commuter cases per archetype', ml: 196, onClick: i => toggleSet(st.arch, i, S.arch.length) });
  const mrows = MODE_KEYS.map((k, i) => ({ label: MODE_NAMES[i], v: F.filter(a => a.m === i).length, color: modeCol(i), icon: i, off: !st.mode.has(i) }));
  hbar('chMode', mrows, { label: 'Commuter cases per main transport', ml: 120, onClick: i => toggleSet(st.mode, i, 6) });
  histogram('chTT');
  arrChart();
  const at = S.arch.map((ar, i) => ({ label: ar.name.replace('Private rental – ', 'Rental – '), v: median(F.filter(a => a.a === i).map(a => a.T / 60)), color: archCol(i), off: !st.arch.has(i) }));
  hbar('chArchTT', at, { label: 'Median travel time by archetype', ml: 196, fmt: v => v ? v.toFixed(1) + ' min' : '–' });
  const fr = FACS.map((f, i) => ({ label: f.name + ' · ' + f.key, v: F.filter(a => a.f === i).length, color: facCol(i), off: !st.fac.has(i), extra: f.hu + ' · ' + fmt(f.admissions) + ' admitted in 2026' }));
  hbar('chFac', fr, { label: 'Commuter cases per faculty', ml: 196, onClick: i => toggleSet(st.fac, i, FACS.length) });
  bldChart();
  // spark under the slider: total travelling
  const tot = new Float64Array(NB); SER.tr.forEach(s => s.forEach((v, i) => tot[i] += v));
  const mx = Math.max(1, ...tot); let d = 'M0 36';
  for (let b = 0; b < NB; b++) d += 'L' + ((b + .5) * 5).toFixed(1) + ' ' + (36 - tot[b] / mx * 32).toFixed(1);
  $('spark').innerHTML = `<path d="${d}L1440 36Z" fill="var(--accent)" opacity=".28"/><path d="${d.replace('M0 36L', 'M')}" fill="none" stroke="var(--accent)" stroke-width="1.2" vector-effect="non-scaling-stroke"/>`;
}
function toggleSet(set, i, n) {
  if (set.size === n) { set.clear(); set.add(i); }
  else if (set.has(i)) { set.delete(i); if (!set.size) for (let k = 0; k < n; k++) set.add(k); }
  else set.add(i);
  applyFilter();
}

/* ---------- KPIs ---------- */
function renderKPIs() {
  const n = F.length || 1;
  const share = ms => Math.round(F.filter(a => ms.includes(a.m)).length / n * 100);
  const tot = new Float64Array(NB); SER.tr.forEach(s => s.forEach((v, i) => tot[i] += v));
  let pb = 0; for (let b = 1; b < NB; b++) if (tot[b] > tot[pb]) pb = b;
  const k = [
    [fmt(F.length), 'szimulált hallgató'],
    [median(F.map(a => a.T / 60)).toFixed(0) + ' perc', 'medián út, ajtótól ajtóig'],
    [share([0, 1]) + ' %', 'gyalog vagy kerékpárral'],
    [share([2, 3, 4]) + ' %', 'busszal vagy vonattal'],
    [share([5]) + ' %', 'autóval'],
    [fmt(tot[pb]) + ' @ ' + hhmm(pb * BIN), 'egyszerre úton (csúcs)'],
  ];
  if (PK) {
    let bi = -1; PK.forEach((P, i) => { if (st.bld.has(i) && (bi < 0 || P.peak > PK[bi].peak)) bi = i; });
    if (bi >= 0) k.push([bldShort(bi) + ' · ' + fmt(PK[bi].peak) + ' @ ' + hhmm(PK[bi].peakT * 60), 'legzsúfoltabb épület (csúcs)']);
  }
  $('kpis').innerHTML = k.map(([b, s]) => `<div class="kpi"><b>${b}</b><span>${s}</span></div>`).join('');
  const all = F.length === A.length;
  $('fCount').textContent = all ? 'All ' + fmt(A.length) + ' cases' : fmt(F.length) + ' of ' + fmt(A.length) + ' cases';
  $('railCount').textContent = all ? '' : fmt(F.length);
  $('caseN').textContent = fmt(F.length);
  $('dinfo').textContent = all ? 'Minden hallgató' : 'Szűrve: ' + fmt(F.length) + ' hallgató';
}

/* ---------- filters UI ---------- */
