  ac.querySelectorAll('.chip').forEach(b => b.onclick = () => toggleSet(st.arch, +b.dataset.i, S.arch.length));
  const counts = MODE_KEYS.map((_, i) => A.filter(a => a.m === i).length);
  const fc = $('facChips');
  fc.innerHTML = FACS.map((f, i) => `<button type="button" class="chip" data-i="${i}" aria-pressed="${st.fac.has(i)}"><span class="dot" style="background:${facCol(i)}"></span>${f.name}<span class="n">${f.key} · ${f.n}</span></button>`).join('');
  fc.querySelectorAll('.chip').forEach(b => b.onclick = () => toggleSet(st.fac, +b.dataset.i, FACS.length));
  const bc = $('bldChips');
