  if (st.transit) el.insertAdjacentHTML('beforeend', `<div class="row" style="color:var(--ink-2)"><span class="sw"><i style="width:22px;height:12px;border-radius:3px;background:#6DB463"></i></span>busz / vonat a vonalszámmal és a rajta utazó hallgatókkal${st.oneway && !st.view3d ? ' · <b style="color:var(--oneway)">›</b> one-way street' : ''}</div>`);
  if (st.view3d) el.insertAdjacentHTML('beforeend', `<div class="row" style="color:var(--ink-2)">Terep ${Math.round(TP.zmin)}–${Math.round(TP.zmax)} m tszf. · piros oszlop = épp bent lévők</div>`);
