/* ---------- table ---------- */
let sorted = [];
function renderRows(reset) {
  if (reset) { st.rowsShown = 150; sorted = F.slice().sort((a, b) => a.tr[0][1] - b.tr[0][1]); }
  const rows = sorted.slice(0, st.rowsShown).map(a => `<tr data-id="${a.id}"${st.sel === a ? ' class="sel"' : ''}><td class="mono">${a.id}</td><td><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${archCol(a.a)};margin-right:6px"></span>${S.arch[a.a].name.replace('Private rental – ', 'Rental – ')}</td><td>${disp(a.place)}</td><td><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${facCol(a.f)};margin-right:6px"></span>${FACS[a.f].key}</td><td>${bldShort(a.b)}</td><td>${a.ch.map(m => iconSVG(m)).join(' ')}</td><td class="mono">${hhmm(a.tr[0][1])}</td><td class="mono">${hhmm(a.arrive)}</td><td class="mono">${hhmm(a.leave)}</td><td class="mono">${(a.T / 60).toFixed(1)}</td><td class="mono">${a.km.toFixed(2)}</td></tr>`).join('');
  $('rows').innerHTML = rows;
  $('rowsInfo').textContent = `Showing ${fmt(Math.min(st.rowsShown, sorted.length))} of ${fmt(sorted.length)} cases, sorted by time leaving home`;
  $('more').hidden = st.rowsShown >= sorted.length;
}
